const choice = $json.choices?.[0];
const content = choice?.message?.content;
const finishReason = choice?.finish_reason;
const webhookBody = $('Receive Operator Intent').first().json.body || {};
const context = $('Get Intent Context').first().json;

function retryOutput(reason) {
  return [{
    json: {
      retry_needed: true,
      llm_action: 'RETRY_INTENT_GENERATION',
      retry_reason: reason,
      llm_raw_content: content || null,
      llm_finish_reason: finishReason,
      llm_usage: $json.usage,
      errors: [reason]
    }
  }];
}

function buildCandidate(extracted) {
  return {
    patch_id: `patch-${Date.now()}`,
    trt_id: context.current_trt.trt_id,
    base_version: context.current_trt.version,
    operator_id: webhookBody.operator_id,
    intent_text: webhookBody.intent_text,
    reason: webhookBody.reason,
    line_id: extracted.line_id,
    target_scope: extracted.target_scope || (extracted.line_id ? 'SINGLE_LINE' : 'SINGLE_LINE'),
    target_lines: extracted.target_lines || [],
    request_types: extracted.request_types || extracted.detected_request_types || [],
    goal: extracted.goal,
    priority: extracted.priority ?? null,
    allowed_instruments: extracted.allowed_instruments ?? null,
    excluded_instruments: extracted.excluded_instruments ?? null,
    kpi_updates: extracted.kpi_updates || {},
    tooling_policy: extracted.tooling_policy || null,
    abnormal_strategy: extracted.abnormal_strategy || null,
    status: 'REVIEWED'
  };
}

if (finishReason === 'length') {
  return retryOutput('Intent candidate generation reached max_tokens before producing complete JSON.');
}
if (!content) {
  return retryOutput('vLLM response did not include choices[0].message.content.');
}

let extracted;
try {
  extracted = typeof content === 'string' ? JSON.parse(content) : content;
} catch (error) {
  return retryOutput(`Could not parse vLLM candidate JSON: ${error.message}`);
}

const candidate = buildCandidate(extracted);
const rejection_reasons = extracted.action === 'PROPOSE_PATCH' ? [] : [extracted.action, ...(extracted.clarification_questions || []), ...(extracted.unsupported_terms || [])];
return [{ json: { retry_needed: false, candidate, llm_extracted: extracted, llm_action: extracted.action, rejection_reasons, llm_raw_content: content, llm_finish_reason: finishReason, llm_usage: $json.usage, errors: [] } }];

const choice = $json.choices?.[0];
const content = choice?.message?.content;
const finishReason = choice?.finish_reason;
const webhookBody = $('Receive Operator Intent').first().json.body || {};
const context = $('Get Intent Context').first().json;

function failed(reason) {
  return [{
    json: {
      retry_needed: false,
      candidate: null,
      llm_extracted: null,
      llm_action: 'NEEDS_REVISION',
      rejection_reasons: ['Intent candidate generation failed after retry.'],
      llm_raw_content: content || null,
      llm_finish_reason: finishReason,
      llm_usage: $json.usage,
      retry_failed_reason: reason,
      errors: ['Intent candidate generation failed after retry.']
    }
  }];
}

if (finishReason === 'length') {
  return failed('retry_finish_reason_length');
}
if (!content) {
  return failed('retry_empty_content');
}

let extracted;
try {
  extracted = typeof content === 'string' ? JSON.parse(content) : content;
} catch (error) {
  return failed(`retry_invalid_json: ${error.message}`);
}

const candidate = {
  patch_id: `patch-${Date.now()}`,
  trt_id: context.current_trt.trt_id,
  base_version: context.current_trt.version,
  operator_id: webhookBody.operator_id,
  intent_text: webhookBody.intent_text,
  reason: webhookBody.reason,
  line_id: extracted.line_id,
  target_scope: extracted.target_scope || (extracted.line_id ? 'SINGLE_LINE' : 'SINGLE_LINE'),
  target_lines: extracted.target_lines || [],
  request_types: extracted.request_types || extracted.detected_request_types || [],
  goal: extracted.goal,
  priority: extracted.priority ?? null,
  allowed_instruments: extracted.allowed_instruments ?? null,
  excluded_instruments: extracted.excluded_instruments ?? null,
  kpi_updates: extracted.kpi_updates || {},
  tooling_policy: extracted.tooling_policy || null,
  abnormal_strategy: extracted.abnormal_strategy || null,
  status: 'REVIEWED'
};
const rejection_reasons = extracted.action === 'PROPOSE_PATCH' ? [] : [extracted.action, ...(extracted.clarification_questions || []), ...(extracted.unsupported_terms || [])];
return [{ json: { retry_needed: false, candidate, llm_extracted: extracted, llm_action: extracted.action, rejection_reasons, llm_raw_content: content, llm_finish_reason: finishReason, llm_usage: $json.usage, errors: [] } }];

const result = $input.first().json;

if (result.intent_patch) {
  return [{ json: result }];
}

const source = $('Receive Operator Intent').first().json;
const sourceContext = source.context || {};

function collectStrings(value, output = []) {
  if (value === null || value === undefined) return output;
  if (typeof value === 'string') {
    output.push(value);
    try {
      const parsed = JSON.parse(value);
      collectStrings(parsed, output);
    } catch (error) {
      const start = value.indexOf('{');
      const end = value.lastIndexOf('}');
      if (start >= 0 && end > start) {
        try {
          collectStrings(JSON.parse(value.slice(start, end + 1)), output);
        } catch (nestedError) {}
      }
    }
    return output;
  }
  if (typeof value === 'number' || typeof value === 'boolean') {
    output.push(String(value));
    return output;
  }
  if (Array.isArray(value)) {
    for (const item of value) collectStrings(item, output);
    return output;
  }
  if (typeof value === 'object') {
    if (value.detail) collectStrings(value.detail, output);
    if (value.errorDescription) collectStrings(value.errorDescription, output);
    if (value.errorMessage) collectStrings(value.errorMessage, output);
    if (value.message) collectStrings(value.message, output);
    if (value.description) collectStrings(value.description, output);
    if (value.error) collectStrings(value.error, output);
    if (value.response) collectStrings(value.response, output);
    if (value.body) collectStrings(value.body, output);
  }
  return output;
}

function bestErrorMessage(value) {
  const candidates = collectStrings(value).map(item => item.trim()).filter(Boolean);
  const businessReasons = candidates.filter(item => item.includes('line_2 is currently in ERROR mode'));
  if (businessReasons.length) return businessReasons.sort((a, b) => a.length - b.length)[0];
  const details = candidates.filter(item => item.includes('Resolve the line error') || item.includes('currently in ERROR mode'));
  if (details.length) return details.sort((a, b) => a.length - b.length)[0];
  const first = candidates.find(item => item !== '[object Object]');
  return first || 'Normalize Domain Candidate with Python failed.';
}

const message = bestErrorMessage(result);

return [{
  json: {
    status: 'REJECTED',
    context: {
      ...sourceContext,
      operator_id: sourceContext.operator_id || source.body?.operator_id || source.operator_id || null,
      scenario_spec_ids: sourceContext.scenario_spec_ids || []
    },
    ids: {
      patch_id: null,
      release_id: null,
      audit_id: null,
      trt_id: sourceContext.trt_id || null,
      trt_version: sourceContext.trt_version || null,
      reconciliation_plan_id: null,
      scenario_spec_id: null
    },
    payload: {
      message,
      source_node: 'Normalize Domain Candidate with Python'
    },
    errors: [message]
  }
}];

const input = $input.first().json;
return [{
  json: {
    status: input.status,
    context: input.context || {},
    ids: input.ids || {},
    payload: input.payload || {},
    errors: input.errors || []
  }
}];

const validation = $input.first().json;
const source = $('Receive Operator Intent').first().json;
const candidatePatch = $('Normalize Domain Candidate with Python').item.json.intent_patch;

function affectedLinesFromOperations(operations) {
  const seen = new Set();
  for (const operation of operations || []) {
    const parts = String(operation.path || '').split('/').filter(Boolean);
    const lineIndex = parts.indexOf('lines');
    if (lineIndex >= 0 && parts[lineIndex + 1]) seen.add(parts[lineIndex + 1]);
  }
  return Array.from(seen).sort();
}

const affectedLines = affectedLinesFromOperations(candidatePatch.operations);
const sourceContext = source.context || {};
return [{
  json: {
    status: 'REVIEWED',
    context: {
      ...sourceContext,
      operator_id: sourceContext.operator_id || source.body?.operator_id || source.operator_id || null,
      patch_id: candidatePatch.patch_id,
      release_id: sourceContext.release_id || null,
      audit_id: sourceContext.audit_id || null,
      trt_id: candidatePatch.trt_id,
      trt_version: candidatePatch.base_version,
      reconciliation_plan_id: sourceContext.reconciliation_plan_id || null,
      scenario_batch_id: sourceContext.scenario_batch_id || null,
      scenario_spec_ids: sourceContext.scenario_spec_ids || [],
      affected_lines: affectedLines
    },
    ids: {
      patch_id: candidatePatch.patch_id,
      release_id: null,
      audit_id: null,
      trt_id: candidatePatch.trt_id,
      trt_version: candidatePatch.base_version,
      reconciliation_plan_id: null,
      scenario_spec_id: null,
      affected_lines: affectedLines
    },
    payload: {
      candidate_patch: candidatePatch,
      affected_lines: affectedLines,
      validation_results: validation.validation_results,
      message: 'Candidate patch is valid. Operator confirmation is required before release.'
    },
    errors: []
  }
}];
